/* Современная: тёплая бумага, тушь, бронза; антиква во вкладках и заголовках */
#ribbon{background:var(--paper);border-bottom:1px solid var(--line)}
.rtabs{height:34px;padding:0 14px;background:var(--paper);border-bottom:1px solid var(--line-soft);gap:4px}
.rtab{font-family:var(--т-заг);font-weight:700;font-size:15.5px;letter-spacing:.01em;color:#8a7d6c;padding:0 12px;height:100%;
  border-bottom:2px solid transparent;transition:color .15s}
.rtab:hover{background:transparent;color:var(--ink)}
.rtab[aria-selected="true"]{background:transparent;color:var(--ink);border-bottom-color:var(--accent)}
.rtab[data-tab="file"]{color:var(--accent)}
.brand svg tspan:first-child{fill:#201f1d} .brand svg tspan:last-child{fill:#b68235}
.brand svg > rect:first-of-type,.brand svg path{stroke:#201f1d} .brand svg circle{fill:#b68235} .brand svg rect[rx=".8"]{fill:#b68235}
.rbody{background:var(--chrome);padding-left:8px;padding-right:8px;padding-top:4px}
.rgroup{border-right:1px solid var(--line)}
.glabel{font-family:var(--т-заг);font-weight:700;font-size:11.5px;line-height:12px;font-style:italic;color:#8a7d6c;letter-spacing:.02em;height:13px;white-space:nowrap}
.rgroup button.мелк svg{width:16px;height:16px}
.rgroup button.круп,.rgroup button.мелк{border-radius:6px}
.rgroup button.круп span{font-weight:500}
.rgroup button:hover{background:var(--paper);border-color:var(--line);box-shadow:0 1px 2px rgba(64,44,18,.08)}
.rgroup button:active{background:var(--accent-weak)}
.rgroup button[aria-pressed="true"]{background:var(--accent-weak);border-color:#e3c48f;color:#7d5411}
.rgroup select,.rgroup input{border-radius:5px;border-color:var(--line);background:var(--paper)}
.rgroup .уголок:hover{background:var(--accent-weak);color:var(--accent)}
#fbar{background:var(--paper);height:32px;border-bottom:1px solid var(--line)}
#addr{border-radius:6px;background:var(--chrome);border-color:var(--line);font-family:var(--т-шрифт);font-weight:500}
#fx{font-family:var(--т-заг);font-style:italic;font-weight:700;font-size:17px;color:var(--accent)}
#formula:focus{border-color:var(--accent)}
#fxOpen{border-radius:6px}
#tabs,#views{background:var(--chrome);border-top:1px solid var(--line)}
#tabs{padding:0 10px 6px}
#tabs .tab{border-radius:0 0 8px 8px;border:1px solid transparent;border-top:0;margin-top:0;padding:0 12px;font-size:12px;color:var(--muted)}
#tabs .tab:hover{background:var(--chrome-2)}
#tabs .tab[aria-selected="true"]{background:var(--paper);border-color:var(--line);color:var(--ink);font-weight:500;box-shadow:inset 0 2px 0 var(--accent)}
#tabs .add{border-radius:50%;width:22px;height:22px;background:var(--paper);border-color:var(--line);color:var(--accent);font-weight:600}
#status,#статус{background:var(--chrome);font-family:var(--т-шрифт);font-size:11px;color:var(--muted)}
#status b,#статус b{color:var(--ink);font-weight:600}
#ctxMenu{padding:6px}
#ctxMenu button{border-radius:7px}
#ctxMenu button:hover{background:var(--accent-weak)}
#ctxMenu hr{border-top-color:var(--line-soft)}
