:is(#auDlg,#bordersDlg,#catalogDlg .cg-box,#cmpDlg,#condDlg,#dvDlg,#findDlg,#fxDlg,#fxWin,#linksDlg,#nmDlg,#paramDlg,#pivotDlg,#plPermsDlg .plp-box,#prDlg,#printDlg,#progress,#pvLinksWin,.plug-окно,.pv-box,.ход-окно,#macroDlg,#vbaDlg,#formDlg,.цвет-окно,#темаОкно,.окно .тело,#задачаОкно,#окноМетрик .тело,#окноШаблона .тело) h3,.plug-окно .pw-имя,#catalogDlg h2,#catalogDlg h3{font-family:var(--т-заг);font-weight:var(--т-заг-вес)}
:is(#auDlg,#bordersDlg,#catalogDlg .cg-box,#cmpDlg,#condDlg,#dvDlg,#findDlg,#fxDlg,#fxWin,#linksDlg,#nmDlg,#paramDlg,#pivotDlg,#plPermsDlg .plp-box,#prDlg,#printDlg,#progress,#pvLinksWin,.plug-окно,.pv-box,.ход-окно,#macroDlg,#vbaDlg,#formDlg,.цвет-окно,#темаОкно,.окно .тело,#задачаОкно,#окноМетрик .тело,#окноШаблона .тело,#ctxMenu,.plug-menu,.ptree-menu,#dvPick,#fnList,#fnHint,#ntHint,#ntPop,#report,.ce-pop,.pv-pop,#fmenu,#менюДок,#пульс-меню,#менюКарты,#отборМеню) :is(button,input,select,textarea):not([type=checkbox]):not([type=radio]):not([type=color]):not([type=range]){border-radius:var(--т-р)}
