/* кнопки цвета на ленте — без серой подложки кнопки браузера */
.rgroup .цветкн{background:transparent}
/* Древний Египет: папирус, лазурит и золото, кайма-фриз под вкладками, имена в картуше */
#ribbon{background:repeating-linear-gradient(0deg,rgba(150,110,40,.05) 0 1px,transparent 1px 4px),
  repeating-linear-gradient(90deg,rgba(150,110,40,.035) 0 1px,transparent 1px 9px),#f6ead0;border-bottom:1px solid #c9a65c}
/* полоса вкладок: лазурит, под ней фриз — золото, лазурит, бирюза, сердолик */
.rtabs{height:37px;padding:0 12px;align-items:flex-start;border-bottom:0;gap:2px;
  background:repeating-linear-gradient(90deg,#c99a2e 0 3px,#1f4aa8 3px 13px,#c99a2e 13px 16px,#1f9a8a 16px 26px,#c99a2e 26px 29px,#b03a22 29px 39px) left 31px/100% 6px no-repeat,
  linear-gradient(#1b3f93,#163274) left top/100% 31px no-repeat,#163274}
.brand{height:31px}
.rtab{font-family:var(--т-заг);font-size:14px;text-transform:uppercase;letter-spacing:.12em;color:#e6c66a;padding:0 13px;height:27px;margin-top:4px;
  border:1px solid transparent;border-bottom:0;border-radius:4px 4px 0 0;background:transparent}
.rtab:hover{color:#ffe08a;background:rgba(255,224,138,.08)}
.rtab[aria-selected="true"]{color:#163274;background:#f6ead0;border-color:#c99a2e;box-shadow:inset 0 2px 0 #c99a2e}
.brand svg tspan:first-child{fill:#ffe08a} .brand svg tspan:last-child{fill:#e6c66a}
.brand svg > rect:first-of-type,.brand svg path{stroke:#ffe08a} .brand svg circle{fill:#e8664a} .brand svg rect[rx=".8"]{fill:#4fd1c0}
.rbody{background:transparent;padding-left:8px;padding-right:8px;padding-top:4px}
.rgroup{border-right:1px solid #d8bf86;box-shadow:1px 0 0 rgba(255,255,255,.6)}
.glabel{font-family:var(--т-заг);font-size:10.5px;text-transform:uppercase;letter-spacing:.14em;color:#8a6a2e;white-space:nowrap}
.rgroup button.круп,.rgroup button.мелк{border-radius:3px;color:var(--лента-текст)}
.rgroup button.мелк svg{width:16px;height:16px}
.rgroup button:hover{background:#fff7e3;border-color:#c99a2e;box-shadow:0 1px 0 rgba(140,100,30,.18)}
.rgroup button:active{background:#f1dfae}
.rgroup button[aria-pressed="true"]{background:#e2e8f6;border-color:#1f4aa8;color:#163274}
.rgroup select,.rgroup input,.rgroup #zoomVal{border-color:#c9a65c;background:#fffaf0;border-radius:3px}
.rgroup .уголок:hover{background:#e2e8f6;color:#1f4aa8}
#ribbon .rbody::-webkit-scrollbar-thumb{background:#d2b26c}
#fbar{background:#fbf4e1;height:32px;border-bottom:1px solid #d8bf86}
/* адрес клетки — в картуше, как имя фараона */
#addr{border:1.5px solid #c99a2e;border-radius:999px;background:#fffaf0;font-family:var(--т-заг);font-size:13px;letter-spacing:.06em;color:#163274;
  box-shadow:inset 0 0 0 2px #fffaf0,inset 0 0 0 3px rgba(201,154,46,.45)}
#fx{font-family:var(--т-заг);font-size:16px;color:#b03a22}
#formula:focus{border-color:#1f4aa8;background:#fffaf0}
#fxOpen{border-radius:3px;border-color:#c9a65c}
#tabs,#views{background:#f1e3bf;border-top:2px solid #c99a2e}
#tabs{padding:0 10px 6px}
#tabs .tab{border-radius:0 0 4px 4px;border:1px solid transparent;border-top:0;padding:0 12px;font-family:var(--т-заг);font-size:13px;letter-spacing:.04em;color:#7a6340}
#tabs .tab:hover{background:#f8eccd;color:var(--ink)}
#tabs .tab[aria-selected="true"]{background:#fbf4e1;border-color:#c9a65c;color:#163274;box-shadow:inset 0 2px 0 #1f4aa8}
#tabs .add{border-radius:50%;width:22px;height:22px;background:#fbf4e1;border-color:#c99a2e;color:#1f4aa8}
#status,#статус{background:linear-gradient(#1b3f93,#163274);border-top:2px solid #c99a2e;color:#e6c66a;font-family:var(--т-заг);font-size:12px;letter-spacing:.05em}
#status b,#stSel,#статус b{color:#ffe08a}
#ctxMenu{padding:5px;background:#fbf4e1}
#ctxMenu button{border-radius:3px}
#ctxMenu button:hover{background:#e2e8f6;color:#163274}
#ctxMenu hr{border-top-color:#e0cb98}
