  font-size:18px;letter-spacing:.06em;text-transform:uppercase;color:#163274;padding-bottom:4px;border-bottom:2px solid #c99a2e}
.plug-окно .pw-шапка{background:linear-gradient(#1b3f93,#163274);color:#ffe08a;border-bottom:2px solid #c99a2e}
.plug-окно .pw-имя{font-size:16px;letter-spacing:.08em;text-transform:uppercase}
.plug-окно .pw-закрыть{color:#ffe08a}
#пульс-демо .пульс-демо-окно button,button[data-act="ok"],button.main,.pw-низ button.main{background:linear-gradient(#2252b8,#173a8a)!important;border-color:#c99a2e!important;
  color:#fff3c8!important;font-weight:600;letter-spacing:.03em}
button[data-act="ok"]:hover,button.main:hover{background:linear-gradient(#2a5fcf,#1b45a3)!important}
#plugPanel{border-left:2px solid #c99a2e}
#plugPanel .pp-head{background:linear-gradient(#1b3f93,#163274);color:#ffe08a;border-bottom:2px solid #c99a2e}
#plugPanel .pp-head b{font-family:var(--т-заг);font-size:15px;letter-spacing:.1em;text-transform:uppercase}
#plugPanel .pp-head button{color:#ffe08a;border-color:#c99a2e;background:transparent}
#plugPanel .pp-sec > b{font-family:var(--т-заг);letter-spacing:.12em;color:#8a6a2e}
